#include <stdio.h>

int main(void) {
    int n, i, total = 0;
    scanf("%d", &n);
    for (i = 1; i <= n; i++) {
        total += i;
    }
    printf("%d\n", total);
    return 0;
}

#include <stdio.h>

int main(void) {
    int n, i, count = 0;
    scanf("%d", &n);
    for (i = 1; i <= n; i++) {
        if (i % 2 == 0) {
            count++;
        }
    }
    printf("%d\n", count);
    return 0;
}
